const types = ['pages','posts','campaign','causes','awards','alumni_story','news','csr','allstory','casestudy','events_list','annual_report','annual_contributors','legacy_project','batch_legacy','jobs','dean_desk','dean_circle','leadership_circle','giving_circle','chairman_circle','director_circle'];
const base = 'https://acr.iitbombay.org/wp-json/wp/v2/';
// Blocklist arrives via Get Blocklist row (direct input) — blocked pages treated as orphans (purged).
const _bl = ($input.first() && $input.first().json ? $input.first().json.paths : null);
const BLOCK = new Set(Array.isArray(_bl) ? _bl : String(_bl || '').replace(/^{|}$/g, '').split(',').filter(Boolean));
const live = new Set();
for (const t of types) {
  let page = 1;
  while (true) {
    let items;
    try { items = await this.helpers.httpRequest({ method: 'GET', url: base + t, json: true, qs: { status: 'publish', per_page: 100, page, _fields: 'id,link' } }); } catch (e) { break; }
    if (!Array.isArray(items) || items.length === 0) break;
    for (const it of items) {
      if (it.id === 2) continue; // Sample Page
      const p = (() => { try { return new URL(it.link).pathname.replace(/\/$/, ''); } catch { return String(it.link || '').replace(/\/$/, ''); } })();
      if (BLOCK.has(p)) continue; // blocked — exclude from live so it is purged
      live.add(it.id + '|' + t);
    }
    if (items.length < 100) break;
    page++;
  }
}
return [{ json: { liveKeys: [...live] } }];

const rows = $input.all();
const live = new Set($('Fetch Live IDs').first().json.liveKeys);
const orphans = [];
for (const r of rows) {
  const k = r.json.post_id + '|' + r.json.source_type;
  if (!live.has(k)) orphans.push(k);
}
return orphans.length ? [{ json: { orphans } }] : [];
